  // Keep tombstoned vectors: forward rows are unchanged.
  s = vector_indexer->merge(source_indexers, nullptr, merge_options);
  CHECK_RETURN_STATUS_EXPECTED(s);
  s = vector_indexer->flush();
  CHECK_RETURN_STATUS_EXPECTED(s);

  return vector_indexer;
}

